from pathlib import Path
import ast
ROOT = Path(__file__).resolve().parent
PKG = ROOT / 'qseries_v2/oracle_execution/solana_atomic_executor'
DEST = PKG / 'mtr_151_bound_simulation_verifier.py'
TEST = ROOT / 'test_mtr_151_bound_simulation_verifier.py'
MODULE = '"""MTR-151: bound simulation/economics revalidation; no transaction creation."""\nimport hashlib\nfrom decimal import Decimal\nfrom dataclasses import replace\nfrom types import MappingProxyType\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_147_protected_economics_gate import ProtectedEvidence, ProtectedCandidateGate\n\nclass BoundSimulationVerifier:\n    """Pass only evidence independently checked by injected canonical inspectors.\n\n    The inspectors MUST use real native instruction decoding and chain data;\n    fixtures are only used by tests. Passing booleans from candidate data is\n    never sufficient. This class does not call RPC, compile or sign.\n    """\n    def __init__(self, inspect_compiled=None, inspect_economics=None):\n        self.inspect_compiled = inspect_compiled\n        self.inspect_economics = inspect_economics\n        self._bound = None\n\n    def bind(self, compiled, simulation, evidence):\n        self._bound = None\n        if not isinstance(evidence, ProtectedEvidence):\n            return False\n        if not isinstance(compiled, dict) or not isinstance(simulation, dict):\n            return False\n        raw = compiled.get(\'raw\')\n        if type(raw) is not bytes or not raw:\n            return False\n        if simulation.get(\'err\', \'MISSING\') is not None:\n            return False\n        if type(simulation.get(\'units\')) is not int or simulation[\'units\'] <= 0:\n            return False\n        if not callable(self.inspect_compiled) or not callable(self.inspect_economics):\n            return False\n        try:\n            tx = self.inspect_compiled(raw)\n            econ = self.inspect_economics(raw, tx, simulation)\n        except Exception:\n            return False\n        if not isinstance(tx, dict) or not isinstance(econ, dict):\n            return False\n        expected_tx = {\'route_id\': evidence.route_id,\n                       \'direction\': evidence.direction,\n                       \'size_sol\': evidence.size_sol,\n                       \'generation\': evidence.generation,\n                       \'atomic_two_leg\': True, \'pump_bounds\': True,\n                       \'dlmm_bounds\': True, \'unsigned_simulation_only\': True}\n        if any(tx.get(k) != v for k, v in expected_tx.items()):\n            return False\n        expected_econ = {\n            \'input_lamports\': evidence.input_lamports,\n            \'minimum_final_lamports\': evidence.minimum_final_lamports,\n            \'network_fee_lamports\': evidence.network_fee_lamports,\n            \'priority_fee_lamports\': evidence.priority_fee_lamports,\n            \'rent_and_residue_lamports\': evidence.rent_and_residue_lamports}\n        if any(type(econ.get(k)) is not int or econ[k] != v\n               for k, v in expected_econ.items()):\n            return False\n        digest = hashlib.sha256(raw).hexdigest()\n        if evidence.verifier_receipt != digest:\n            return False\n        self._bound = (evidence, digest)\n        return True\n\n    def __call__(self, evidence):\n        return type(evidence) is ProtectedEvidence and self._bound is not None and self._bound == (evidence, evidence.verifier_receipt)\n\ndef evaluate_bound(compiled, simulation, evidence, *, route_id,\n                   generation, inspect_compiled=None, inspect_economics=None):\n    verifier = BoundSimulationVerifier(inspect_compiled, inspect_economics)\n    if not verifier.bind(compiled, simulation, evidence):\n        return MappingProxyType({\'status\': \'HOLD\', \'reason\': \'CANONICAL_EVIDENCE_NOT_BOUND\'})\n    return ProtectedCandidateGate(verifier).evaluate(\n        evidence, expected_route=route_id, expected_generation=generation)\n\nif __name__ == \'__main__\':\n    print(\'[MTR151] VERIFIER_BINDING_ADAPTER_IMPORT_PASS\')\n    print(\'[NATIVE_INSPECTORS] NOT_CONNECTED\')\n    print(\'[SIMULATION_INVOKED] FALSE\')\n    print(\'[OFFICIAL_PROFIT_CERTIFIED] FALSE\')\n    print(\'[PRODUCTION_CUTOVER] FALSE\')\n    print(\'[PRIVATE_KEY] NOT_USED\')\n    print(\'[SIGNING] FALSE\')\n    print(\'[BROADCAST] FALSE\')\n'
TEST_SOURCE = "import hashlib\nimport unittest\nfrom dataclasses import replace\nfrom decimal import Decimal\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_147_protected_economics_gate import ProtectedEvidence\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_151_bound_simulation_verifier import evaluate_bound\n\nRAW = b'unit-test-only-unsigned-transaction'\nDIGEST = hashlib.sha256(RAW).hexdigest()\nBASE = ProtectedEvidence('r', 'PUMP_TO_METEORA', Decimal('0.010'), 9,\n                         10000000, 10100000, 5000, 1000, 1000,\n                         True, True, True, DIGEST)\nSIM = {'err': None, 'units': 120000, 'logs': []}\n\ndef native(raw):\n    assert raw == RAW\n    return dict(route_id='r', direction='PUMP_TO_METEORA',\n                size_sol=Decimal('0.010'), generation=9,\n                atomic_two_leg=True, pump_bounds=True, dlmm_bounds=True,\n                unsigned_simulation_only=True)\n\ndef economics(raw, tx, sim):\n    return {k: getattr(BASE, k) for k in ('input_lamports',\n         'minimum_final_lamports', 'network_fee_lamports',\n         'priority_fee_lamports', 'rent_and_residue_lamports')}\n\ndef go(e=BASE, raw=RAW, sim=SIM, inspector=native, econ=economics):\n    return evaluate_bound({'raw': raw}, sim, e, route_id='r', generation=9,\n                          inspect_compiled=inspector, inspect_economics=econ)\n\nclass Tests(unittest.TestCase):\n    def test_missing_native_inspector_holds(self):\n        self.assertEqual(go(inspector=None)['status'], 'HOLD')\n    def test_simulation_error_holds(self):\n        self.assertEqual(go(sim={'err': {'InstructionError': [0, 'Failed']}, 'units': 3})['status'], 'HOLD')\n    def test_missing_units_holds(self):\n        self.assertEqual(go(sim={'err': None})['status'], 'HOLD')\n    def test_digest_mismatch_holds(self):\n        self.assertEqual(go(e=replace(BASE, verifier_receipt='wrong'))['status'], 'HOLD')\n    def test_swapped_route_holds(self):\n        self.assertEqual(go(e=replace(BASE, route_id='other'))['status'], 'HOLD')\n    def test_wrong_economics_holds(self):\n        def bad(*args):\n            return dict(economics(*args), minimum_final_lamports=9900000)\n        self.assertEqual(go(econ=bad)['status'], 'HOLD')\n    def test_native_inspector_cannot_claim_one_leg(self):\n        def one_leg(raw):\n            return dict(native(raw), atomic_two_leg=False)\n        self.assertEqual(go(inspector=one_leg)['status'], 'HOLD')\n    def test_fixture_positive_not_execution(self):\n        r = go()\n        self.assertEqual(r['status'], 'REVALIDATION_CANDIDATE')\n        self.assertEqual(r['net_lamports'], 93000)\n        self.assertFalse(r['signing_authorized'])\n        self.assertFalse(r['broadcast_authorized'])\n    def test_not_profitable_holds(self):\n        low = replace(BASE, minimum_final_lamports=10000000)\n        def econ_low(*args):\n            return dict(economics(*args), minimum_final_lamports=10000000)\n        self.assertEqual(go(e=low, econ=econ_low)['reason'], 'NOT_PROTECTED_POSITIVE')\n\nif __name__ == '__main__':\n    unittest.main(verbosity=2)\n"
if not (PKG / 'mtr_147_protected_economics_gate.py').is_file():
    raise SystemExit('[HOLD] MTR-147 not installed')
for src in (MODULE, TEST_SOURCE):
    ast.parse(src)
DEST.write_text(MODULE, encoding='utf-8')
TEST.write_text(TEST_SOURCE, encoding='utf-8')
print('[PASS] MTR-151 installed')
print('[SCOPE] COMPILED_SIMULATION_BINDING_STAGED; native inspectors pending')
print('[SCANNER] FROZEN')
print('[PRIVATE_KEY] NOT_USED')
print('[SIGNING] FALSE')
print('[BROADCAST] FALSE')
